ALTER TABLE tcomptes
ADD CONSTRAINT tcomptes_ibfk_2 FOREIGN KEY (masse_bilantaire)
REFERENCES tmasse_bilantaire (id) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `usp_tcomptes_Update`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE usp_tcomptes_Update (IN p_id int,
IN p_numero varchar(6),
IN p_intitule varchar(100),
IN p_classe_id int,
IN p_id_naturecompte int)
BEGIN
  START TRANSACTION;

    UPDATE tcomptes
    SET numero = p_numero,
        intitule = p_intitule,
        masse_bilantaire = p_classe_id,
        id_naturecompte = p_id_naturecompte
    WHERE id = p_id;


    -- Begin Return row code block

    SELECT
      numero,
      intitule,
      masse_bilantaire,
      id_naturecompte
    FROM tcomptes
    WHERE id = p_id;

  -- End Return row code block


  COMMIT;
END
$$

