--
-- Create procedure `usp_tcomptes_Insert`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE usp_tcomptes_Insert (IN p_numero varchar(6),
IN p_intitule varchar(100),
IN p_masse_bilantaire nvarchar(100),
IN p_naturecompte nvarchar(100))
BEGIN
  DECLARE _id_masse_bilantaire int;
  DECLARE _id_naturecompte int;

  SET _id_masse_bilantaire = (SELECT
      id
    FROM tmasse_bilantaire
    WHERE intitule = p_masse_bilantaire);
  SET _id_naturecompte = (SELECT
      id_nature
    FROM tnature_compte
    WHERE nature_compte = p_naturecompte);
  START TRANSACTION;

    INSERT INTO tcomptes (numero, intitule, masse_bilantaire, id_naturecompte)
      VALUES (p_numero, p_intitule, _id_masse_bilantaire, _id_naturecompte);


    -- Begin Return row code block

    SELECT
      numero,
      intitule,
      masse_bilantaire,
      id_naturecompte
    FROM tcomptes
    WHERE id = LAST_INSERT_ID();

  -- End Return row code block


  COMMIT;
