-- Create view `v_presences`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_presences
AS
SELECT
  `p`.`id` AS `id_presence`,
  `pers`.`nom` AS `nom`,
  `pers`.`postnom` AS `postnom`,
  `pers`.`prenom` AS `prenom`,
  `p`.`heure_arrivee` AS `heure_arrivee`,
  `p`.`heure_sortie` AS `heure_sortie`,
  `p`.`est_ferie` AS `est_ferie`
FROM (`tpresences` `p`
  JOIN `tpersonnel` `pers`
    ON (`p`.`id_agent` = `pers`.`id`))
ORDER BY `p`.`heure_arrivee` DESC;

