--
-- Create view `v_ventes_clients`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_ventes_clients
AS
SELECT
  `v`.`id` AS `id_vente`,
  `v`.`date_vente` AS `date_vente`,
  `c`.`raison_sociale` AS `client`,
  `v`.`montant_total_vente` AS `montant_total_vente`,
  `v`.`montant_payee` AS `montant_payee`,
  `v`.`type_paiement` AS `type_paiement`,
  `v`.`etat_paiement` AS `etat_paiement`
FROM (`tventeproduitfini` `v`
  LEFT JOIN `tclient` `c`
    ON (`v`.`client_id` = `c`.`id`))
ORDER BY `v`.`date_vente` DESC;

--
-- Create view `v_balance_agee_clients`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_balance_agee_clients
AS
SELECT
  `c`.`id` AS `client_id`,
  `c`.`raison_sociale` AS `client`,
  `v`.`date_vente` AS `date_vente`,
  `v`.`montant_total_vente` AS `montant_total_vente`,
  `v`.`montant_payee` AS `montant_payee`,
  `v`.`montant_total_vente` - `v`.`montant_payee` AS `solde_du`,
  TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) AS `jours_retard`,
  CASE WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) <= 30 THEN '0-30 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) BETWEEN 31 AND 60 THEN '31-60 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) BETWEEN 61 AND 90 THEN '61-90 jours' ELSE '+90 jours' END AS `tranche_age`
FROM (`tventeproduitfini` `v`
  JOIN `tclient` `c`
    ON (`v`.`client_id` = `c`.`id`))
WHERE `v`.`montant_total_vente` - `v`.`montant_payee` > 0
ORDER BY CASE WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) <= 30 THEN '0-30 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) BETWEEN 31 AND 60 THEN '31-60 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) BETWEEN 61 AND 90 THEN '61-90 jours' ELSE '+90 jours' END, `v`.`date_vente`;

--
-- Create table `tpaiements_clients`
