  libelle varchar(200) NOT NULL,
  montant_paye decimal(10, 2) NOT NULL,
  um enum ('USD', 'CDF') DEFAULT 'USD',
  type_paiement enum ('Comptant', 'Crédit', 'Anticipation') NOT NULL,
  statut_paiement enum ('Réglé', 'Partiel', 'Annulé') DEFAULT 'Réglé',
  PRIMARY KEY (id_paiement)
