  mode_amortissement enum ('lineaire', 'degressif') NOT NULL,
  periodicite enum ('Mensuel', 'Annuel') DEFAULT 'Mensuel',
  duree_utilisation int(11) NOT NULL,
  valeur_residuelle decimal(15, 2) DEFAULT 0.00,
  provenance varchar(100) DEFAULT NULL,
  statut enum ('en service', 'en maintenance', 'hors service', 'vendu') DEFAULT 'en service',
  Coefficient_degressif varchar(255) DEFAULT NULL,
  column1 int(11) DEFAULT NULL,
  PRIMARY KEY (id_materiel)
)
ENGINE = INNODB,
CHARACTER SET utf8mb4,
