--
-- Create table `tplan_amortissements`
--
CREATE TABLE tplan_amortissements (
  id_amort int(11) NOT NULL AUTO_INCREMENT,
  id_materiel int(11) NOT NULL,
  date_calcul date NOT NULL,
  valeur_base decimal(15, 2) NOT NULL,
  taux decimal(15, 2) NOT NULL,
  duree decimal(15, 2) NOT NULL,
  mensualite decimal(15, 2) NOT NULL,
  annuite decimal(15, 2) NOT NULL,
  amort_cumule decimal(15, 2) NOT NULL,
  valeur_nette decimal(15, 2) NOT NULL,
  PRIMARY KEY (id_amort)
)
ENGINE = INNODB,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_uca1400_ai_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create foreign key
--
ALTER TABLE tplan_amortissements
ADD CONSTRAINT tplan_amortissements_ibfk_1 FOREIGN KEY (id_materiel)
REFERENCES tmateriels (id_materiel);

DELIMITER $$

--
-- Create procedure `pr_insert_plan_amort`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE pr_insert_plan_amort (IN _id_materiel int,
IN _date_amort date,
IN _valeur_base decimal(15, 2),
IN _taux decimal(15, 2),
IN _periodicite varchar(20),
IN _duree decimal(15, 2),
IN _valeur_nette decimal(15, 2),
IN _mode_amort varchar(40),
IN _Coefficient_degressif int)
BEGIN
  DECLARE _valeur_base2 decimal(15, 2);
  DECLARE _mensualite decimal(10, 2);
  DECLARE _annuite decimal(10, 2);
  DECLARE _amort_cumule decimal(10, 2) DEFAULT 0;
  DECLARE _valeur_nette2 decimal(15, 2);
  DECLARE _date_calc date;
  DECLARE i int DEFAULT 1;

  -- Initialisation des valeurs
  SET _valeur_nette2 = _valeur_nette;
  SET _valeur_base2 = _valeur_base;
  SET _date_calc = _date_amort;

  -- Boucle pour générer le plan
  WHILE i <= _duree DO

    -- Mise à jour de la date en fonction de la périodicité
    IF (_periodicite = 'Mensuel') THEN
      SET _date_calc = LAST_DAY(DATE_ADD(_date_amort, INTERVAL i MONTH));
    ELSEIF (_periodicite = 'Annuel') THEN
      -- Fixer la date de calcul au 31 décembre de chaque année
      SET _date_calc = STR_TO_DATE(CONCAT(YEAR(_date_amort) + i, '-12-31'), '%Y-%m-%d');
    END IF;

    -- Calcul des montants d'amortissement
    IF (_mode_amort = 'lineaire') THEN
      SET _annuite = (_valeur_base / _duree);
      SET _mensualite = _annuite / 12;
    ELSEIF (_mode_amort = 'degressif') THEN
      SET _annuite = (_valeur_base2 * (100 / _duree) * _Coefficient_degressif);
      SET _mensualite = (_valeur_base2 * (100 / _duree) * _Coefficient_degressif) / 12;
    END IF;

    -- Mise à jour des cumuls
    SET _amort_cumule = _amort_cumule + _mensualite;
    SET _valeur_nette2 = _valeur_base - _amort_cumule;

    -- Insertion dans le plan d'amortissement
    INSERT INTO tplan_amortissements (id_materiel,
    date_calcul,
    valeur_base,
    taux,
    duree,
    mensualite,
    annuite,
    amort_cumule,
    valeur_nette)
      VALUES
      (
      _id_materiel,
      _date_calc,
      _valeur_base2,
      _taux,
      _duree,
      _mensualite,
      _annuite,
      _amort_cumule,
      _valeur_nette2
      );

    -- Préparation pour l'itération suivante
    SET _valeur_base2 = _valeur_nette2;
    SET i = i + 1;
  END WHILE;

  -- Retour de confirmation
  SELECT
    CONCAT('Plan d''amortissement généré pour le matériel ID : ', _id_materiel) AS Message;

END
$$

DELIMITER ;

--
-- Create view `v_plan_amortissement`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_plan_amortissement
AS
SELECT
  `m`.`id_materiel` AS `id_materiel`,
  `m`.`code_materiel` AS `code_materiel`,
  `m`.`designation` AS `designation`,
  `m`.`date_acquisition` AS `date_acquisition`,
  `m`.`valeur_acquisition` AS `valeur_acquisition`,
  `m`.`taux_amortissement` AS `taux_amortissement`,
  `m`.`mode_amortissement` AS `mode_amortissement`,
  `p`.`date_calcul` AS `date_calcul`,
  `p`.`mensualite` AS `mensualite`,
  `p`.`annuite` AS `annuite`,
  `p`.`amort_cumule` AS `amort_cumule`,
  `p`.`valeur_nette` AS `valeur_nette`
FROM (`tmateriels` `m`
  JOIN `tplan_amortissements` `p`
    ON (`m`.`id_materiel` = `p`.`id_materiel`))
ORDER BY `m`.`id_materiel`, `p`.`date_calcul`;

