--
-- Create view `v_stock_matiere`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_stock_matiere
AS
SELECT
  `mp`.`id` AS `id_matiere`,
  `mp`.`reference` AS `reference`,
  `mp`.`designation` AS `designation`,
  `mp`.`stock_actuel` AS `stock_actuel`,
  COALESCE(SUM(`ent`.`quantite`), 0) AS `total_entrees`,
  COALESCE(SUM(`sort`.`quantite`), 0) AS `total_sorties`
FROM ((`tmatierepremiere` `mp`
  LEFT JOIN `tentreematiere` `ent`
    ON (`mp`.`id` = `ent`.`matiere_premiere_id`))
  LEFT JOIN `tsortiematiere` `sort`
    ON (`mp`.`id` = `sort`.`matiere_premiere_id`))
GROUP BY `mp`.`id`,
         `mp`.`reference`,
         `mp`.`designation`,
         `mp`.`stock_actuel`;

--
-- Create view `v_balance_agee_fournisseurs`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_balance_agee_fournisseurs
AS
SELECT
  `f`.`id` AS `id_agent`,
  CONCAT(`f`.`nom`, ' ', `f`.`postnom`, ' ', `f`.`prenom`) AS `Agent_achat`,
  `ach`.`date_entree` AS `date_entree`,
  `ach`.`quantite` * `ach`.`prix_unitaire_entree` AS `montant_total`,
  `ach`.`montant_payer` AS `montant_payer`,
  `ach`.`quantite` * `ach`.`prix_unitaire_entree` - `ach`.`montant_payer` AS `solde_du`,
  TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) AS `jours_retard`,
  CASE WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) <= 30 THEN '0-30 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) BETWEEN 31 AND 60 THEN '31-60 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) BETWEEN 61 AND 90 THEN '61-90 jours' ELSE '+90 jours' END AS `tranche_age`
FROM (`tentreematiere` `ach`
  JOIN `tagent_achat` `f`
    ON (`ach`.`id` = `f`.`id`))
WHERE `ach`.`quantite` * `ach`.`prix_unitaire_entree` - `ach`.`montant_payer` > 0
ORDER BY CASE WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) <= 30 THEN '0-30 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) BETWEEN 31 AND 60 THEN '31-60 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) BETWEEN 61 AND 90 THEN '61-90 jours' ELSE '+90 jours' END, `ach`.`date_entree`;

--
-- Create view `v_balance_agee_consolide`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_balance_agee_consolide
AS
SELECT
  `c`.`id` AS `client_id`,
  `c`.`raison_sociale` AS `client`,
  `v`.`date_vente` AS `date_vente`,
  `v`.`montant_total_vente` AS `montant_total_vente`,
  `v`.`montant_payee` AS `montant_payee`,
  `v`.`montant_total_vente` - `v`.`montant_payee` AS `solde_du`,
  TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) AS `jours_retard`,
  CASE WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) <= 30 THEN '0-30 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) BETWEEN 31 AND 60 THEN '31-60 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`v`.`date_vente`) BETWEEN 61 AND 90 THEN '61-90 jours' ELSE '+90 jours' END AS `tranche_age`
FROM (`tventeproduitfini` `v`
  JOIN `tclient` `c`
    ON (`v`.`client_id` = `c`.`id`))
WHERE `v`.`montant_total_vente` - `v`.`montant_payee` > 0
UNION ALL
SELECT
  `f`.`id` AS `id_agent`,
  CONCAT(`f`.`nom`, ' ', `f`.`postnom`, ' ', `f`.`prenom`) AS `Agent_achat`,
  `ach`.`date_entree` AS `date_entree`,
  `ach`.`quantite` * `ach`.`prix_unitaire_entree` AS `montant_total`,
  `ach`.`montant_payer` AS `montant_payer`,
  `ach`.`quantite` * `ach`.`prix_unitaire_entree` - `ach`.`montant_payer` AS `solde_du`,
  TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) AS `jours_retard`,
  CASE WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) <= 30 THEN '0-30 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) BETWEEN 31 AND 60 THEN '31-60 jours' WHEN TO_DAYS(CURDATE()) - TO_DAYS(`ach`.`date_entree`) BETWEEN 61 AND 90 THEN '61-90 jours' ELSE '+90 jours' END AS `tranche_age`
FROM (`tentreematiere` `ach`
  JOIN `tagent_achat` `f`
    ON (`ach`.`id` = `f`.`id`))
WHERE `ach`.`quantite` * `ach`.`prix_unitaire_entree` - `ach`.`montant_payer` > 0
ORDER BY `tranche_age`;

