      id,
      journal_id,
      numdocument,
      sous_compte_id,
      sens,
      libelle,
      sous_compte_cp,
      date_ecriture,
      montant,
      um,
      taux_convertion_usd_fc
    FROM tecritures_comptables
    ;

  COMMIT;
END
$$

--
-- Create procedure `usp_tecritures_comptables_Insert`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE usp_tecritures_comptables_Insert (IN p_journal_id int,
IN p_numdocument varchar(10),
IN p_sous_compte_id int,
IN p_sens enum ('''C''', '''CP'''),
IN p_libelle text,
IN p_sous_compte_cp int,
IN p_date_ecriture datetime,
IN p_montant decimal(15, 2),
IN p_um enum ('''USD''', '''FC'''),
IN p_taux_convertion_usd_fc decimal(10, 2))
BEGIN
  START TRANSACTION;

    INSERT INTO tecritures_comptables (journal_id, numdocument, sous_compte_id, sens, libelle, sous_compte_cp,
    date_ecriture, montant, um, taux_convertion_usd_fc)
      VALUES (p_journal_id, p_numdocument, p_sous_compte_id, p_sens, p_libelle, p_sous_compte_cp, p_date_ecriture,
      p_montant, p_um, p_taux_convertion_usd_fc);


    -- Begin Return row code block

    SELECT
      journal_id,
      numdocument,
      sous_compte_id,
      sens,
      libelle,
      sous_compte_cp,
      date_ecriture,
      montant,
      um,
      taux_convertion_usd_fc
    FROM tecritures_comptables
    WHERE id = LAST_INSERT_ID();

  -- End Return row code block


  COMMIT;
END
$$

