--
-- Create view `v_synthese_financiere`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_synthese_financiere
AS
SELECT
  `n`.`nature_compte` AS `nature_compte`,
  `c`.`numero` AS `compte`,
  `c`.`intitule` AS `compte_intitule`,
  `sc`.`numero` AS `sous_compte`,
  `sc`.`intitule` AS `sous_compte_intitule`,
  SUM(CASE WHEN `n`.`nature_compte` = 'ACTIF' AND
      `e`.`sens` = 'CP' THEN `e`.`montant` WHEN `n`.`nature_compte` = 'ACTIF' AND
      `e`.`sens` = 'C' THEN -`e`.`montant` WHEN `n`.`nature_compte` = 'PASSIF' AND
      `e`.`sens` = 'C' THEN `e`.`montant` WHEN `n`.`nature_compte` = 'PASSIF' AND
      `e`.`sens` = 'CP' THEN -`e`.`montant` WHEN `n`.`nature_compte` = 'CHARGES' AND
      `e`.`sens` = 'CP' THEN `e`.`montant` WHEN `n`.`nature_compte` = 'CHARGES' AND
      `e`.`sens` = 'C' THEN -`e`.`montant` WHEN `n`.`nature_compte` = 'PRODUITS' AND
      `e`.`sens` = 'C' THEN `e`.`montant` WHEN `n`.`nature_compte` = 'PRODUITS' AND
      `e`.`sens` = 'CP' THEN -`e`.`montant` ELSE 0 END) AS `solde`
FROM (((`tecritures_comptables` `e`
  JOIN `tsous_comptes` `sc`
    ON (`e`.`sous_compte_id` = `sc`.`id`))
  JOIN `tcomptes` `c`
    ON (`sc`.`compte_id` = `c`.`id`))
  JOIN `tnature_compte` `n`
    ON (`c`.`id_naturecompte` = `n`.`id_nature`))
GROUP BY `n`.`nature_compte`,
         `c`.`numero`,
         `c`.`intitule`,
         `sc`.`numero`,
         `sc`.`intitule`
ORDER BY FIELD(`n`.`nature_compte`, 'ACTIF', 'PASSIF', 'CHARGES', 'PRODUITS'), `c`.`numero`, `sc`.`numero`;

--
-- Create view `v_resultat_net`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_resultat_net
AS
SELECT
  SUM(CASE WHEN `n`.`nature_compte` = 'CHARGES' AND
      `e`.`sens` = 'CP' THEN `e`.`montant` WHEN `n`.`nature_compte` = 'CHARGES' AND
      `e`.`sens` = 'C' THEN -`e`.`montant` WHEN `n`.`nature_compte` = 'PRODUITS' AND
      `e`.`sens` = 'C' THEN `e`.`montant` WHEN `n`.`nature_compte` = 'PRODUITS' AND
      `e`.`sens` = 'CP' THEN -`e`.`montant` ELSE 0 END) AS `resultat_net`
FROM (((`tecritures_comptables` `e`
  JOIN `tsous_comptes` `sc`
    ON (`e`.`sous_compte_id` = `sc`.`id`))
  JOIN `tcomptes` `c`
    ON (`sc`.`compte_id` = `c`.`id`))
  JOIN `tnature_compte` `n`
    ON (`c`.`id_naturecompte` = `n`.`id_nature`))
WHERE `n`.`nature_compte` IN ('CHARGES', 'PRODUITS');

--
-- Create view `v_journal_operations`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_journal_operations
AS
SELECT
  `e`.`id` AS `id_ecriture`,
  `e`.`date_ecriture` AS `date_ecriture`,
  `e`.`libelle` AS `libelle`,
  `c`.`numero` AS `compte`,
  `c`.`intitule` AS `compte_intitule`,
  `sc`.`numero` AS `sous_compte`,
  `sc`.`intitule` AS `sous_compte_intitule`,
  CASE WHEN `e`.`sens` = 'CP' THEN `e`.`montant` ELSE 0 END AS `debit`,
  CASE WHEN `e`.`sens` = 'C' THEN `e`.`montant` ELSE 0 END AS `credit`,
  `e`.`um` AS `um`,
  `e`.`numdocument` AS `numdocument`,
  `e`.`id_user` AS `id_user`
FROM ((`tecritures_comptables` `e`
  JOIN `tsous_comptes` `sc`
    ON (`e`.`sous_compte_id` = `sc`.`id`))
  JOIN `tcomptes` `c`
    ON (`sc`.`compte_id` = `c`.`id`))
ORDER BY `e`.`date_ecriture`, `e`.`id`;

