--
-- Create view `v_balance_generale`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW v_balance_generale
AS
SELECT
  `c`.`numero` AS `compte`,
  `c`.`intitule` AS `compte_intitule`,
  SUM(CASE WHEN `e`.`sens` = 'CP' THEN `e`.`montant` ELSE 0 END) AS `total_debit`,
  SUM(CASE WHEN `e`.`sens` = 'C' THEN `e`.`montant` ELSE 0 END) AS `total_credit`,
  SUM(CASE WHEN `e`.`sens` = 'CP' THEN `e`.`montant` ELSE 0 END) - SUM(CASE WHEN `e`.`sens` = 'C' THEN `e`.`montant` ELSE 0 END) AS `solde`
FROM ((`tecritures_comptables` `e`
  JOIN `tsous_comptes` `sc`
    ON (`e`.`sous_compte_id` = `sc`.`id`))
  JOIN `tcomptes` `c`
    ON (`sc`.`compte_id` = `c`.`id`))
GROUP BY `c`.`numero`,
         `c`.`intitule`
ORDER BY `c`.`numero`;

