--
-- Create table `troles`
--
CREATE TABLE troles (
  id int(11) NOT NULL AUTO_INCREMENT,
  nom_role varchar(50) NOT NULL,
  description text DEFAULT NULL,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AUTO_INCREMENT = 5,
AVG_ROW_LENGTH = 4096,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_uca1400_ai_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `nom_role` on table `troles`
--
ALTER TABLE troles
ADD UNIQUE INDEX nom_role (nom_role);

--
-- Create table `tutilisateurs`
--
CREATE TABLE tutilisateurs (
  id int(11) NOT NULL AUTO_INCREMENT,
  nom_utilisateur varchar(50) NOT NULL,
  mot_de_passe varchar(255) NOT NULL,
  email varchar(100) DEFAULT NULL,
  statut enum ('Actif', 'Inactif') DEFAULT 'Actif',
  role_id int(11) DEFAULT NULL,
  date_creation timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AUTO_INCREMENT = 2,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_uca1400_ai_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `nom_utilisateur` on table `tutilisateurs`
--
ALTER TABLE tutilisateurs
ADD UNIQUE INDEX nom_utilisateur (nom_utilisateur);

--
-- Create foreign key
--
ALTER TABLE tutilisateurs
ADD CONSTRAINT tutilisateurs_ibfk_1 FOREIGN KEY (role_id)
REFERENCES troles (id);

DELIMITER $$

--
-- Create procedure `pr_login_user`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE pr_login_user (IN _nom_utilisateur varchar(50),
IN _mot_de_passe varchar(255))
BEGIN
  DECLARE v_user_id int;
  DECLARE v_role_id int;
  DECLARE v_statut varchar(10);

  -- Vérifier si l'utilisateur existe
  SELECT
    id,
    role_id,
    statut INTO v_user_id, v_role_id, v_statut
  FROM tutilisateurs
  WHERE nom_utilisateur = _nom_utilisateur
  AND mot_de_passe = SHA2(_mot_de_passe, 256)
  LIMIT 1;

  -- Si utilisateur non trouvé
  IF v_user_id IS NULL THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Nom d''utilisateur ou mot de passe incorrect';
  END IF;

  -- Si utilisateur inactif
  IF v_statut = 'Inactif' THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Utilisateur inactif, contactez l''administrateur';
  END IF;

  -- Retourner les infos utilisateur avec le rôle
  SELECT
    u.id AS utilisateur_id,
    u.nom_utilisateur,
    u.email,
    u.statut,
    r.nom_role,
    r.description AS role_description
  FROM tutilisateurs u
    JOIN troles r
      ON u.role_id = r.id
  WHERE u.id = v_user_id;

END
$$

--
-- Create procedure `pr_create_user`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE pr_create_user (IN _nom_utilisateur varchar(50),
IN _mot_de_passe varchar(255),
IN _email varchar(100),
IN _role_id int)
BEGIN
  -- Vérifier si l’utilisateur existe déjà
  IF EXISTS (SELECT
        1
      FROM tutilisateurs
      WHERE nom_utilisateur = _nom_utilisateur) THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Utilisateur déjà existant';
  ELSE
    INSERT INTO tutilisateurs (nom_utilisateur, mot_de_passe, email, role_id)
      VALUES (_nom_utilisateur, SHA2(_mot_de_passe, 256), _email, _role_id);
  END IF;
END
$$

DELIMITER ;

