--
USE db_pvc_renovee;

--
-- Drop trigger `trigger1`
--
DROP TRIGGER IF EXISTS trigger1;

--
-- Set default database
--
USE db_pvc_renovee;

DELIMITER $$

--
-- Create trigger `trigger1`
--
CREATE
DEFINER = 'root'@'localhost'
TRIGGER trigger1
AFTER INSERT
ON tmateriels
FOR EACH ROW
BEGIN

  SET @_id_materiel = new.id_materiel;
  SET @_date_amort = new.date_acquisition;
  SET @_valeur_base = new.valeur_acquisition;
  SET @_taux = new.taux_amortissement;
  SET @_periodicite = new.periodicite;
  SET @_duree = new.duree_utilisation;
  SET @_valeur_nette = new.valeur_residuelle;
  SET @_mode_amort = new.mode_amortissement;
  SET @_Coefficient_degressif = new.Coefficient_degressif;
  CALL pr_insert_plan_amort(@_id_materiel, @_date_amort, @_valeur_base, @_taux, @_periodicite, @_duree, @_valeur_nette, @_mode_amort, @_Coefficient_degressif);

END
$$

DELIMITER ;

